-- Robotics/Embedded/IoT pathway ("Vector Division") Act 10 -- "Control"
-- content, under world-vec-control (already inserted by the Acts 6-10
-- spine migration, 20260813120000). 1 campaign, 2 operations, 12 missions
-- (11 lessons + boss), following the same campaigns -> operations ->
-- missions -> dialogue -> objectives -> challenges -> hints pattern as
-- every other Act. No new ChallengeType needed -- reuses story_dialogue,
-- multiple_choice, drag_and_drop, investigation, interactive_diagram,
-- browser_simulation (generic console fallback) and boss_encounter.
--
-- This is the pathway's most significant story beat since Act 1: a
-- SECOND, live, currently-ongoing incident, distinct from the recovered
-- Act 1/4 door -- a robotic arm at a Nexus reactor cooling facility
-- oscillating instead of holding position. The reveal keeps the same
-- restraint used for every prior reveal in this pathway (the silent
-- circuit, 0xDEAD, the frozen controller, the e-stop flaw): this is an
-- ordinary, explainable engineering failure, not malice. Nothing
-- reprogrammed the loop. Its proportional gain was tuned correctly three
-- decades ago for bearings that were new; those bearings wore down every
-- year since, until a sensor error small enough to have always been
-- harmless started producing motion large enough to be dangerous.
-- SUBSTRATE did not attack the loop -- it simply never stopped trusting a
-- tuning the physical machine had quietly outgrown. Closes on the pivot
-- into Act 11, "The RTOS."

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-control', 'world-vec-control', 'control', '10A - Control', 'A robotic arm at a Nexus reactor cooling facility will not hold still. Learn the vocabulary of closed-loop control -- open versus closed loop, feedback, setpoints, error signals, proportional, integral and derivative control, PID intuition, tuning, overshoot, oscillation and control-loop sampling -- fast enough to stabilize a live machine before real damage happens.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-control-1', 'campaign-vec-control', 'closing-the-loop', 'Closing the Loop', 'Open versus closed loop, feedback, setpoints, error signals, proportional control and integral control.', 1),
  ('operation-vec-control-2', 'campaign-vec-control', 'tuning-under-pressure', 'Tuning Under Pressure', 'Derivative control, PID intuition, tuning, overshoot and oscillation, control-loop sampling, and diagnosing the live reactor arm.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-control-01', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-1', 'open-vs-closed-loop', 'Open Loop vs Closed Loop', 'A robotic arm at a Nexus reactor cooling facility begins oscillating instead of holding its commanded position -- a live incident, not a recovered artifact, and every second it continues is a second closer to real damage.', 'beginner', ARRAY['imani','tomas','byte'], null, null, '{"type":"simulation","simulationId":"open-vs-closed-loop-sim"}'::jsonb, '{"xp":170,"credits":20}'::jsonb, false, 1),
  ('mission-vec-control-02', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-1', 'feedback', 'Feedback', 'Every closed loop needs one thing an open loop never has: a way for the system to find out what it actually did.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-control-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"feedback-sim"}'::jsonb, '{"xp":170,"credits":25}'::jsonb, false, 2),
  ('mission-vec-control-03', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-1', 'setpoints', 'Setpoints', 'The arm was never told to oscillate. It was told to hold one exact position -- its setpoint -- and everything it does now is in service of that single number.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-control-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"setpoints-sim"}'::jsonb, '{"xp":180,"credits":25}'::jsonb, false, 3),
  ('mission-vec-control-04', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-1', 'error-signals', 'Error Signals', 'Every correction the arm makes starts from the same single number: how far its current position is from where it is supposed to be.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-control-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"error-signals-sim"}'::jsonb, '{"xp":180,"credits":30}'::jsonb, false, 4),
  ('mission-vec-control-05', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-1', 'proportional-control', 'Proportional Control', 'The simplest possible reaction to an error is to push back against it, harder the bigger the error is. That single idea is proportional control, and it is the term the arm leans on hardest.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-control-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"proportional-control-sim"}'::jsonb, '{"xp":190,"credits":30}'::jsonb, false, 5),
  ('mission-vec-control-06', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-1', 'integral-control', 'Integral Control', 'Proportional control alone almost always leaves a small, permanent gap. Integral control is what finally closes it -- by remembering.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-control-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"integral-control-sim"}'::jsonb, '{"xp":190,"credits":30}'::jsonb, false, 6),
  ('mission-vec-control-07', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-2', 'derivative-control', 'Derivative Control', 'Proportional and integral both react to where the error is. Derivative control is the only term that reacts to where the error is headed.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-control-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"derivative-control-sim"}'::jsonb, '{"xp":200,"credits":35}'::jsonb, false, 7),
  ('mission-vec-control-08', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-2', 'pid-intuition', 'PID Intuition', 'Three terms, three completely different jobs. Understanding PID is not memorizing formulas -- it is knowing exactly which term to blame for exactly which kind of misbehavior.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-control-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"pid-intuition-sim"}'::jsonb, '{"xp":200,"credits":35}'::jsonb, false, 8),
  ('mission-vec-control-09', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-2', 'tuning', 'Tuning', 'Choosing Kp, Ki and Kd correctly is not a one-time formality. It is a promise that the numbers still match the physical machine they were chosen for.', 'beginner', ARRAY['tomas','imani'], '{"requiredMissionIds":["mission-vec-control-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"tuning-sim"}'::jsonb, '{"xp":210,"credits":35}'::jsonb, false, 9),
  ('mission-vec-control-10', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-2', 'overshoot-and-oscillation', 'Overshoot and Oscillation', 'Overshoot is a correction that goes too far. Oscillation is what happens when the system keeps overcorrecting for its own overcorrections.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-control-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"overshoot-and-oscillation-sim"}'::jsonb, '{"xp":210,"credits":40}'::jsonb, false, 10),
  ('mission-vec-control-11', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-2', 'control-loop-sampling', 'Control-Loop Sampling', 'A control loop cannot correct a mistake it has not measured yet. How often it measures is its own decision, with its own consequences.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-control-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"control-loop-sampling-sim"}'::jsonb, '{"xp":220,"credits":40}'::jsonb, false, 11),
  ('mission-vec-control-12', 'world-vec-control', 'campaign-vec-control', 'operation-vec-control-2', 'the-oscillating-reactor-arm', 'The Oscillating Reactor Arm', 'Everything this Act taught, aimed at one live machine that will not hold still -- not to blame a part, but to find the one number that quietly stopped matching the arm it was chosen for, before Vector Division tells anyone how to fix it.', 'boss', ARRAY['imani','tomas','byte','sera','substrate'], '{"requiredMissionIds":["mission-vec-control-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-oscillating-reactor-arm-sim"}'::jsonb, '{"xp":850,"credits":180,"badgeIds":["the-oscillating-arm"],"skillXp":{"robotics_fundamentals":110}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-control-01', 1, 'imani', 'A robotic arm at the Nexus reactor cooling facility is oscillating right now instead of holding its commanded position. This is not a recovered artifact on a bench. It is live, and every second it continues is a second closer to real damage near a reactor cooling system.'),
  ('mission-vec-control-01', 2, 'byte', 'I am pulling telemetry off the arm''s controller directly. It is not idle and it is not simply broken -- it is actively measuring its own position and issuing corrections, over and over, and each correction is making the swing worse instead of better.'),
  ('mission-vec-control-01', 3, 'tomas', 'Then before either of you says another word about it, we need to agree on what kind of system we are even looking at. An open-loop system acts on a command and never checks what actually happened. A closed-loop system measures its own result and corrects itself, continuously.'),
  ('mission-vec-control-01', 4, 'tomas', 'Everything the arm is doing right now -- reading its own position, comparing it to where it should be, adjusting -- only happens because it is closed-loop. An open-loop arm could not oscillate like this. It would just move and stop, right or wrong, and never know the difference.'),
  ('mission-vec-control-01', 5, 'imani', 'So the arm is trying to correct itself, and its own corrections are the problem.'),
  ('mission-vec-control-01', 6, 'byte', 'That is what the data suggests. Which means diagnosing this is not going to be about finding a broken part. It is about understanding the loop it is running -- and every concept anyone here already knows about circuits and firmware only gets us to the front door of that problem.'),

  ('mission-vec-control-02', 1, 'tomas', 'Feedback is simple to say and easy to underestimate: it is a system''s own output, routed back in as part of its next input. Nothing more mystical than that.'),
  ('mission-vec-control-02', 2, 'tomas', 'Without feedback, a controller is blind after the moment it acts. With feedback, it never stops finding out how close it actually got.'),
  ('mission-vec-control-02', 3, 'byte', 'The arm''s position sensor is exactly that path. Every correction the motor makes gets measured again, and that new measurement becomes the input to the next correction. It never stops watching itself.'),

  ('mission-vec-control-03', 1, 'tomas', 'A setpoint is the target value a control loop is trying to hold or reach -- a temperature, a speed, an angle. It does not change on its own. Only an operator or a higher-level system changes it.'),
  ('mission-vec-control-03', 2, 'tomas', 'The reactor arm has one setpoint right now: a fixed position, commanded once and unchanged since. Whatever is going wrong, it is not going wrong because anyone moved the target.'),

  ('mission-vec-control-04', 1, 'tomas', 'An error signal is just setpoint minus measured value. Nothing else. It is the one number every controller in this Act actually reacts to.'),
  ('mission-vec-control-04', 2, 'byte', 'Which means the error signal is the arm''s entire picture of how wrong it currently is. It has no idea about bearings, gain, or thirty years of history. It only ever sees this one number, over and over.'),
  ('mission-vec-control-04', 3, 'tomas', 'So before we can explain why the arm is oscillating, we need to see what its own error signal actually looks like over time, not guess at it.'),

  ('mission-vec-control-05', 1, 'tomas', 'Proportional control, the P in PID, is the most direct idea in this Act: correction equals the error, multiplied by a gain constant Kp. Bigger error, bigger correction, in direct proportion.'),
  ('mission-vec-control-05', 2, 'tomas', 'Kp alone decides how hard the system pushes back. Too small, and it responds sluggishly. Too large, and it can push back harder than the physical system can absorb -- overcorrecting every single time.'),

  ('mission-vec-control-06', 1, 'tomas', 'Proportional control reacts to the error right now and forgets it the instant it changes. Which means if a small, steady error persists, a purely proportional system can settle just short of the setpoint forever and call it done.'),
  ('mission-vec-control-06', 2, 'tomas', 'Integral control fixes that by accumulating error over time. The longer a small error persists, the larger the integral term grows, until it finally pushes the system the rest of the way.'),
  ('mission-vec-control-06', 3, 'byte', 'The cost is that accumulated error does not vanish instantly either. Push it too hard for too long and it can overshoot on its own, or keep correcting for a mistake that already stopped existing -- what engineers call windup.'),

  ('mission-vec-control-07', 1, 'tomas', 'Derivative control looks at the rate of change of the error -- how fast it is growing or shrinking -- and produces a correction based on that trend, not the error''s current size.'),
  ('mission-vec-control-07', 2, 'tomas', 'In practice it acts like damping. If the error is closing fast, derivative control eases off before proportional control would, preventing the system from slamming past the setpoint on its own momentum.'),

  ('mission-vec-control-08', 1, 'tomas', 'Put all three together and you get PID: proportional reacts to the error right now, integral reacts to error that has persisted, derivative reacts to how fast the error is changing. Three different questions about the same one number.'),
  ('mission-vec-control-08', 2, 'byte', 'Which means when a real system misbehaves, the shape of the misbehavior usually points straight at which term is out of balance -- sluggish response, a persistent offset, and an overcorrecting swing all look different from each other.'),
  ('mission-vec-control-08', 3, 'tomas', 'That is the actual skill here. Not the math. Reading a symptom and knowing immediately which term is responsible.'),

  ('mission-vec-control-09', 1, 'tomas', 'Tuning is the process of choosing values for Kp, Ki and Kd that match a specific physical system''s actual behavior -- its mass, its friction, its motor strength, all of it.'),
  ('mission-vec-control-09', 2, 'imani', 'Which means tuning is not a math exercise done once in a lab and filed away. It is a claim about a specific machine, at a specific point in its life.'),
  ('mission-vec-control-09', 3, 'tomas', 'Exactly. And nothing about a control loop''s code checks whether that claim is still true years later. The numbers stay exactly as chosen until someone deliberately revisits them.'),

  ('mission-vec-control-10', 1, 'tomas', 'Overshoot is a single correction carrying the system past its setpoint instead of stopping right at it. On its own, one overshoot is not catastrophic -- most well-tuned systems overshoot slightly and settle.'),
  ('mission-vec-control-10', 2, 'byte', 'Oscillation is what happens when overshoot keeps happening on both sides of the setpoint, correction after correction, instead of settling down.'),
  ('mission-vec-control-10', 3, 'tomas', 'And there is a difference worth knowing between oscillation that shrinks over time and oscillation that grows. One settles eventually on its own. The other one gets worse until something intervenes.'),

  ('mission-vec-control-11', 1, 'tomas', 'A digital control loop does not run continuously. It samples -- measures, decides and acts, then waits until the next fixed interval and does it again.'),
  ('mission-vec-control-11', 2, 'byte', 'Sample too slowly and the loop is always correcting based on old, stale information, reacting a beat behind what the system is actually doing right now.'),
  ('mission-vec-control-11', 3, 'tomas', 'Sample too fast, relative to how noisy the sensor is, and the loop can end up reacting to noise itself instead of real motion. Sampling rate is a real design choice, not a free variable to just maximize.'),

  ('mission-vec-control-12', 1, 'imani', 'The arm has been oscillating for six minutes. Facility engineers pulled its emergency brake early, so nobody is hurt, but that also means we lost our live test subject. Everything we send back has to be right the first time, on paper, before Vector Division touches the real hardware again.'),
  ('mission-vec-control-12', 2, 'tomas', 'Then we work it the way we worked the door. Every concept from this Act covers a piece of this. Closed-loop feedback, proportional gain, tuning, overshoot. We rule each one in or out and see what is left standing.'),
  ('mission-vec-control-12', 3, 'sera', 'I want to be clear about why I am here for this one specifically, not as a formality. A sensor that lies is dangerous. An actuator that will not stop is dangerous. But a control loop whose tuning silently stops matching its own hardware is a different category entirely -- nothing ever failed, alarmed, or threw an error. It just quietly became wrong, and that is the failure mode I actually lose sleep over.'),
  ('mission-vec-control-12', 4, 'byte', 'Feedback path confirms end to end -- sensor to controller to motor, continuously, no break anywhere. Whatever this is, it is not an open-loop fault and it is not a dead sensor.'),
  ('mission-vec-control-12', 5, 'substrate', 'PHYSICAL STATE DIVERGES FROM PLAN.'),
  ('mission-vec-control-12', 6, 'byte', '...that came off the facility''s own diagnostic channel mid-scan, not anything addressed to us. Same restrained diagnostic format we have seen before. I do not think it is watching us at all -- I think it is watching the arm, the same way we are.'),
  ('mission-vec-control-12', 7, 'imani', 'Noted. Filed. Not what we are here to solve today. Focus on the loop -- confirm it is closed, find what actually changed, and tell me how to make that arm hold still before someone tries to restart it.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-control-01-o1', 'mission-vec-control-01', 1, 'Tell the loop types apart', 'Distinguish open-loop from closed-loop control before diagnosing anything about the arm.'),
  ('mission-vec-control-01-o2', 'mission-vec-control-01', 2, 'Classify the arm''s control system', 'Based on Byte''s telemetry, judge what kind of system the arm is running, and what that implies for diagnosing it.'),

  ('mission-vec-control-02-o1', 'mission-vec-control-02', 1, 'Define feedback', 'Choose the accurate definition of feedback in a control system.'),
  ('mission-vec-control-02-o2', 'mission-vec-control-02', 2, 'Identify the arm''s feedback path', 'Find the evidence describing the physical path that feeds the arm''s output back into its own controller.'),

  ('mission-vec-control-03-o1', 'mission-vec-control-03', 1, 'Confirm the setpoint is not the problem', 'Judge whether the arm''s instability comes from a changing setpoint or from something else.'),

  ('mission-vec-control-04-o1', 'mission-vec-control-04', 1, 'Define the error signal', 'Choose the accurate definition of an error signal.'),
  ('mission-vec-control-04-o2', 'mission-vec-control-04', 2, 'Read the arm''s error signal', 'Given telemetry, judge what the arm''s error signal is actually doing over time.'),

  ('mission-vec-control-05-o1', 'mission-vec-control-05', 1, 'Define proportional control', 'Choose the accurate description of proportional control.'),
  ('mission-vec-control-05-o2', 'mission-vec-control-05', 2, 'Judge the effect of gain', 'Judge what happens to a system''s response as its proportional gain Kp increases.'),

  ('mission-vec-control-06-o1', 'mission-vec-control-06', 1, 'Define integral control', 'Choose the accurate description of integral control.'),
  ('mission-vec-control-06-o2', 'mission-vec-control-06', 2, 'Explain the steady-state gap', 'Choose the accurate reason a purely proportional system can settle short of its setpoint.'),

  ('mission-vec-control-07-o1', 'mission-vec-control-07', 1, 'Define derivative control', 'Choose the accurate description of derivative control.'),
  ('mission-vec-control-07-o2', 'mission-vec-control-07', 2, 'Judge its effect on oscillation', 'Judge how adding a derivative term would affect a system that is already overshooting and swinging back and forth.'),

  ('mission-vec-control-08-o1', 'mission-vec-control-08', 1, 'Match each term to its role', 'Match proportional, integral and derivative to the question each one answers about the error.'),
  ('mission-vec-control-08-o2', 'mission-vec-control-08', 2, 'Diagnose from the symptom', 'Given a described misbehavior, judge which PID term is most likely responsible.'),

  ('mission-vec-control-09-o1', 'mission-vec-control-09', 1, 'Define tuning correctly', 'Choose the accurate description of what tuning actually is.'),
  ('mission-vec-control-09-o2', 'mission-vec-control-09', 2, 'Find the standing risk', 'Find the evidence pointing to the real risk in any control loop tuned once and left alone.'),

  ('mission-vec-control-10-o1', 'mission-vec-control-10', 1, 'Tell the two patterns apart', 'Choose the accurate distinction between damped and growing oscillation.'),
  ('mission-vec-control-10-o2', 'mission-vec-control-10', 2, 'Read the arm''s telemetry trace', 'Given the arm''s recorded swings, judge whether its oscillation is damped or growing.'),

  ('mission-vec-control-11-o1', 'mission-vec-control-11', 1, 'Define sampling rate correctly', 'Choose the accurate description of what a control loop''s sampling rate determines.'),
  ('mission-vec-control-11-o2', 'mission-vec-control-11', 2, 'Rule sampling in or out', 'Given the arm''s sampling log, judge whether its sampling rate could plausibly be causing the oscillation.'),

  ('mission-vec-control-12-o1', 'mission-vec-control-12', 1, 'Confirm the loop is closed, not broken open', 'Prove the arm''s feedback path is intact and active, ruling out an open-loop failure as the cause.'),
  ('mission-vec-control-12-o2', 'mission-vec-control-12', 2, 'Diagnose the gain problem', 'Using the maintenance log and bearing wear report, judge what has actually changed to make the arm unstable.'),
  ('mission-vec-control-12-o3', 'mission-vec-control-12', 3, 'Rule out sampling and confirm the instability pattern', 'Using the telemetry trace and sampling log, confirm the oscillation is growing and that sampling rate is not the cause.'),
  ('mission-vec-control-12-o4', 'mission-vec-control-12', 4, 'State the diagnosis and the fix', 'Having confirmed the loop is closed, diagnosed the gain problem, and ruled out sampling, state the full diagnosis and the fix.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-control-01-o1-c1', 'mission-vec-control-01-o1', 1, 'drag_and_drop', 'Sort each system into open-loop or closed-loop.', '{"items":[{"id":"i1","text":"A timer-based sprinkler system that runs for ten minutes regardless of soil moisture"},{"id":"i2","text":"Cruise control that reads current speed and adjusts throttle to match a set speed"},{"id":"i3","text":"A toaster that runs a fixed heating cycle regardless of how dark the toast gets"},{"id":"i4","text":"The reactor arm''s controller, reading its own position sensor and adjusting motor output continuously"}],"targets":[{"id":"open","label":"Open-loop"},{"id":"closed","label":"Closed-loop"}]}'::jsonb, '{"correctMapping":{"i1":"open","i2":"closed","i3":"open","i4":"closed"}}'::jsonb),
  ('mission-vec-control-01-o2-c1', 'mission-vec-control-01-o2', 1, 'multiple_choice', 'Byte''s telemetry shows the arm continuously reading its own position and issuing new motor corrections in response. What kind of system is it, and what does that imply?', '{"question":"Byte''s telemetry shows the arm continuously reading its own position and issuing new motor corrections in response. What kind of system is it, and what does that imply?","options":[{"id":"a","text":"Open-loop -- it is simply executing a fixed motion program with a bug in it"},{"id":"b","text":"Closed-loop -- it is actively measuring its own result and correcting itself, which means the problem is somewhere in that correction process, not in a single fixed command"},{"id":"c","text":"Neither -- continuous sensor reads only happen in broken systems"},{"id":"d","text":"Open-loop -- feedback is optional decoration on top of a fixed program"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-control-02-o1-c1', 'mission-vec-control-02-o1', 1, 'multiple_choice', 'Feedback, in a control system, is...', '{"question":"Feedback, in a control system, is...","options":[{"id":"a","text":"Any signal sent from a controller to an actuator"},{"id":"b","text":"A system''s own output routed back in as an input, so it can measure and react to its own results"},{"id":"c","text":"A backup power source for the controller"},{"id":"d","text":"A warning message shown to a human operator"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-control-02-o2-c1', 'mission-vec-control-02-o2', 1, 'investigation', 'Which evidence describes the physical path that feeds the arm''s output back into its own controller?', '{"evidence":[{"id":"e1","label":"Wiring note","detail":"The arm''s position sensor output is wired directly into the same controller that issues motor commands"},{"id":"e2","label":"Facility note","detail":"The arm is bolted to a reinforced mounting plate"},{"id":"e3","label":"Power log","detail":"The arm draws steady current at idle"}],"question":"Which evidence describes the physical path that feeds the arm''s output back into its own controller?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-control-03-o1-c1', 'mission-vec-control-03-o1', 1, 'multiple_choice', 'Facility records show the arm''s commanded setpoint has not changed in the six minutes it has been oscillating. What does that rule out?', '{"question":"Facility records show the arm''s commanded setpoint has not changed in the six minutes it has been oscillating. What does that rule out?","options":[{"id":"a","text":"It rules out the setpoint itself moving or being reissued as the cause -- the loop is failing to hold a target that has stayed perfectly still"},{"id":"b","text":"It proves the sensor is broken"},{"id":"c","text":"It proves the motor is broken"},{"id":"d","text":"It proves nothing, setpoints do not matter here"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-vec-control-04-o1-c1', 'mission-vec-control-04-o1', 1, 'multiple_choice', 'An error signal in a control loop is...', '{"question":"An error signal in a control loop is...","options":[{"id":"a","text":"The difference between the setpoint and the current measured value"},{"id":"b","text":"Any signal that indicates a hardware failure"},{"id":"c","text":"The raw output of the position sensor alone"},{"id":"d","text":"A fixed constant set once at commissioning"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-vec-control-04-o2-c1', 'mission-vec-control-04-o2', 1, 'investigation', 'Given telemetry, what is the arm''s error signal actually doing over time?', '{"evidence":[{"id":"e1","label":"Telemetry trace","detail":"The arm''s error signal crosses zero repeatedly, growing larger in magnitude on each swing rather than shrinking"},{"id":"e2","label":"Facility note","detail":"The arm was last serviced eight years ago"},{"id":"e3","label":"Power log","detail":"Supply voltage stable throughout"}],"question":"Given telemetry, what is the arm''s error signal actually doing over time?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-control-05-o1-c1', 'mission-vec-control-05-o1', 1, 'multiple_choice', 'Proportional control produces a correction that is...', '{"question":"Proportional control produces a correction that is...","options":[{"id":"a","text":"A fixed constant, regardless of the error"},{"id":"b","text":"Directly proportional to the current error, scaled by a gain constant Kp"},{"id":"c","text":"Proportional to how long the error has existed"},{"id":"d","text":"Proportional to how fast the error is changing"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-control-05-o2-c1', 'mission-vec-control-05-o2', 1, 'multiple_choice', 'As Kp increases on a system whose mechanical response has not changed, correction magnitude for the same error...', '{"question":"As Kp increases on a system whose mechanical response has not changed, correction magnitude for the same error...","options":[{"id":"a","text":"Stays exactly the same regardless of Kp"},{"id":"b","text":"Grows -- and past some point, an aggressive enough correction can overshoot the target and provoke an even larger error in the other direction next cycle"},{"id":"c","text":"Always shrinks"},{"id":"d","text":"Has no relationship to Kp at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-control-06-o1-c1', 'mission-vec-control-06-o1', 1, 'multiple_choice', 'Integral control produces a correction based on...', '{"question":"Integral control produces a correction based on...","options":[{"id":"a","text":"The instantaneous error only"},{"id":"b","text":"The accumulated sum of error over time, which eliminates the small steady-state gap proportional control alone would leave"},{"id":"c","text":"The rate of change of the error"},{"id":"d","text":"A value set once and never updated"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-control-06-o2-c1', 'mission-vec-control-06-o2', 1, 'multiple_choice', 'Why can a purely proportional controller settle just short of its setpoint and stay there?', '{"question":"Why can a purely proportional controller settle just short of its setpoint and stay there?","options":[{"id":"a","text":"Because at a small enough error, the proportional correction itself becomes small enough that it can be balanced out and the system simply stops closing the gap"},{"id":"b","text":"Because proportional control always overshoots"},{"id":"c","text":"Because sensors cannot measure small errors"},{"id":"d","text":"Because proportional control ignores error entirely"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-vec-control-07-o1-c1', 'mission-vec-control-07-o1', 1, 'multiple_choice', 'Derivative control produces a correction based on...', '{"question":"Derivative control produces a correction based on...","options":[{"id":"a","text":"How fast the error is currently changing, easing off if the error is already closing quickly"},{"id":"b","text":"The total accumulated error over time"},{"id":"c","text":"A fixed correction unrelated to the error"},{"id":"d","text":"The error''s magnitude alone, same as proportional control"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-vec-control-07-o2-c1', 'mission-vec-control-07-o2', 1, 'multiple_choice', 'A system is overshooting its setpoint and swinging back and forth. What would adding an appropriately-sized derivative term most likely do?', '{"question":"A system is overshooting its setpoint and swinging back and forth. What would adding an appropriately-sized derivative term most likely do?","options":[{"id":"a","text":"Make the oscillation larger"},{"id":"b","text":"Add damping, easing off the correction as the error closes quickly, which tends to reduce overshoot rather than add to it"},{"id":"c","text":"Have no effect on oscillation at all"},{"id":"d","text":"Eliminate the setpoint entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-control-08-o1-c1', 'mission-vec-control-08-o1', 1, 'drag_and_drop', 'Match proportional, integral and derivative to the question each one answers about the error.', '{"items":[{"id":"i1","text":"Proportional"},{"id":"i2","text":"Integral"},{"id":"i3","text":"Derivative"}],"targets":[{"id":"t1","label":"Reacts to how large the error is right now"},{"id":"t2","label":"Reacts to how long a small error has persisted"},{"id":"t3","label":"Reacts to how fast the error is changing"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),
  ('mission-vec-control-08-o2-c1', 'mission-vec-control-08-o2', 1, 'multiple_choice', 'A system reaches its setpoint quickly but then persistently sits a small, fixed amount short of it forever. Which term is most likely too weak?', '{"question":"A system reaches its setpoint quickly but then persistently sits a small, fixed amount short of it forever. Which term is most likely too weak?","options":[{"id":"a","text":"Proportional"},{"id":"b","text":"Integral -- a persistent, unchanging gap over time is exactly the symptom integral control exists to eliminate"},{"id":"c","text":"Derivative"},{"id":"d","text":"None, this cannot be diagnosed from the symptom alone"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-control-09-o1-c1', 'mission-vec-control-09-o1', 1, 'multiple_choice', 'Tuning a control loop means...', '{"question":"Tuning a control loop means...","options":[{"id":"a","text":"Writing the PID code once, correctly, so it never needs attention again"},{"id":"b","text":"Choosing Kp, Ki and Kd to match a specific physical system''s real behavior -- a match that can stop being true if the physical system changes"},{"id":"c","text":"Increasing every gain as high as possible for the fastest response"},{"id":"d","text":"A setting only relevant during initial manufacturing, never afterward"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-control-09-o2-c1', 'mission-vec-control-09-o2', 1, 'investigation', 'Which evidence points to the real risk in any control loop tuned once and left alone?', '{"evidence":[{"id":"e1","label":"Facility maintenance log","detail":"The reactor arm''s Kp value was set during commissioning decades ago and has no record of ever being revisited"},{"id":"e2","label":"Facility note","detail":"The arm''s housing was repainted five years ago"},{"id":"e3","label":"Power log","detail":"Supply voltage has stayed within spec for years"}],"question":"Which evidence points to the real risk in any control loop tuned once and left alone?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-control-10-o1-c1', 'mission-vec-control-10-o1', 1, 'multiple_choice', 'What separates damped oscillation from growing (diverging) oscillation?', '{"question":"What separates damped oscillation from growing (diverging) oscillation?","options":[{"id":"a","text":"They are the same thing with different names"},{"id":"b","text":"Damped oscillation shrinks in amplitude over time toward the setpoint; growing oscillation increases in amplitude with each cycle and will not settle on its own"},{"id":"c","text":"Damped oscillation only happens in software, never in hardware"},{"id":"d","text":"Growing oscillation always means the sensor is broken"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-control-10-o2-c1', 'mission-vec-control-10-o2', 1, 'browser_simulation', 'Given this sequence of peak swings, is the arm''s oscillation damped or growing?', '{"screen":"REACTOR ARM -- POSITION TELEMETRY -- LIVE TRACE","question":"Given this sequence of peak swings, is the arm''s oscillation damped or growing?","records":[{"id":"r1","code":"SWING_1","detail":"Peak deviation: 2.1 degrees from setpoint"},{"id":"r2","code":"SWING_2","detail":"Peak deviation: 3.4 degrees from setpoint, opposite direction"},{"id":"r3","code":"SWING_3","detail":"Peak deviation: 5.0 degrees from setpoint, growing again -- each swing larger than the last, not settling"},{"id":"r4","code":"SWING_4","detail":"Not yet recorded, arm still oscillating"}]}'::jsonb, '{"correctOptionId":"r3"}'::jsonb),

  ('mission-vec-control-11-o1-c1', 'mission-vec-control-11-o1', 1, 'multiple_choice', 'A control loop''s sampling rate determines...', '{"question":"A control loop''s sampling rate determines...","options":[{"id":"a","text":"How often the loop measures, decides and acts -- too slow and it reacts to stale data, too fast relative to sensor noise and it can react to noise instead of real motion"},{"id":"b","text":"Only how much power the controller uses"},{"id":"c","text":"Nothing relevant to control quality, only to logging"},{"id":"d","text":"The system''s setpoint"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-vec-control-11-o2-c1', 'mission-vec-control-11-o2', 1, 'investigation', 'Given the arm''s sampling log, could its sampling rate plausibly be causing the oscillation?', '{"evidence":[{"id":"e1","label":"Sampling log","detail":"The arm''s control loop samples at a fixed rate well within its documented, historically stable specification, unchanged for decades"},{"id":"e2","label":"Facility note","detail":"The arm''s housing is due for repainting"},{"id":"e3","label":"Power log","detail":"The arm draws nominal current"}],"question":"Given the arm''s sampling log, could its sampling rate plausibly be causing the oscillation?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-control-12-o1-c1', 'mission-vec-control-12-o1', 1, 'investigation', 'Which evidence proves the arm''s feedback path is intact and active, ruling out an open-loop failure?', '{"evidence":[{"id":"e1","label":"Bus trace","detail":"The position sensor is reporting continuously and the controller is issuing new motor corrections in direct response, end to end, with no break in the path"},{"id":"e2","label":"Facility note","detail":"The arm was manufactured with an open-loop backup mode, unused in decades"},{"id":"e3","label":"Power log","detail":"Supply voltage nominal throughout"}],"question":"Which evidence proves the arm''s feedback path is intact and active, ruling out an open-loop failure?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-control-12-o2-c1', 'mission-vec-control-12-o2', 1, 'multiple_choice', 'Kp was set decades ago at commissioning and never revisited. Bearing wear has steadily increased every year since, changing how much motion the same correction actually produces. A small, longstanding sensor error that used to be harmless is now driving visible motion. What is actually wrong?', '{"question":"Kp was set decades ago at commissioning and never revisited. Bearing wear has steadily increased every year since, changing how much motion the same correction actually produces. A small, longstanding sensor error that used to be harmless is now driving visible motion. What is actually wrong?","options":[{"id":"a","text":"The proportional gain, chosen correctly for the arm''s original bearings, is now too aggressive for its current, worn mechanical response -- the same correction that used to be appropriate now overcorrects"},{"id":"b","text":"SUBSTRATE reprogrammed the gain value deliberately"},{"id":"c","text":"The position sensor is completely broken and reporting random noise"},{"id":"d","text":"The setpoint was changed without authorization"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-vec-control-12-o3-c1', 'mission-vec-control-12-o3', 1, 'browser_simulation', 'Given these records, what best explains the growing oscillation?', '{"screen":"REACTOR ARM -- FULL DIAGNOSTIC SWEEP","question":"Given these records, what best explains the growing oscillation?","records":[{"id":"r1","code":"SAMPLING_LOG","detail":"Sampling rate unchanged for decades, within spec -- ruled out as a cause"},{"id":"r2","code":"TELEMETRY_TRACE","detail":"Each swing''s peak deviation is larger than the last, a classic growing-oscillation pattern caused by a correction that is consistently too strong for the system''s current damping"},{"id":"r3","code":"SENSOR_CAL","detail":"Position sensor within original calibration tolerance, functioning as designed"},{"id":"r4","code":"POWER_LOG","detail":"Supply voltage nominal throughout the incident"}]}'::jsonb, '{"correctOptionId":"r2"}'::jsonb),
  ('mission-vec-control-12-o4-c1', 'mission-vec-control-12-o4', 1, 'boss_encounter', 'Having confirmed the loop is closed, diagnosed the gain problem, and ruled out sampling, state the full diagnosis and the fix.', '{"stages":[{"objectiveRef":"mission-vec-control-12-o1","label":"Confirm the loop is closed"},{"objectiveRef":"mission-vec-control-12-o2","label":"Diagnose the gain problem"},{"objectiveRef":"mission-vec-control-12-o3","label":"Rule out sampling and confirm the pattern"}],"task":"State the diagnosis in two sentences: nothing reprogrammed the arm''s control loop -- its proportional gain was tuned correctly three decades ago for bearings that were new, and those bearings have worn down every year since, until a sensor error small enough to have always been harmless started producing motion large enough to be dangerous. The fix is to retune the loop for the arm''s current, worn mechanical response -- reducing proportional gain and adding damping appropriate to the hardware as it actually is today, not as it was thirty years ago."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-control-12-o1","mission-vec-control-12-o2","mission-vec-control-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-control-01-o1-c1', 'orientation', 'Ask whether the system checks what actually happened after it acts, or just acts and moves on.', 10, 1),
  ('mission-vec-control-01-o1-c1', 'solution', 'Open-loop: the sprinkler and the toaster, both fixed sequences with no feedback. Closed-loop: cruise control and the reactor arm, both continuously measuring and correcting.', 20, 2),
  ('mission-vec-control-01-o2-c1', 'orientation', 'Weight what continuous sensor reads and continuous corrections actually imply about the system''s design.', 10, 1),
  ('mission-vec-control-01-o2-c1', 'solution', 'Continuous measurement plus continuous correction is closed-loop behavior -- meaning the problem lives inside the correction process itself, not in one bad fixed command.', 20, 2),

  ('mission-vec-control-02-o1-c1', 'orientation', 'Ask which direction the signal travels: does it leave the system, or come back into it?', 10, 1),
  ('mission-vec-control-02-o1-c1', 'solution', 'Feedback is a system''s own output routed back in as an input, letting it measure and react to its own results.', 20, 2),
  ('mission-vec-control-02-o2-c1', 'orientation', 'Look for a wiring detail connecting the sensor output back to the same controller issuing commands.', 10, 1),
  ('mission-vec-control-02-o2-c1', 'solution', 'e1: the position sensor output wired directly into the same controller that issues motor commands is the feedback path.', 20, 2),

  ('mission-vec-control-03-o1-c1', 'orientation', 'Ask whether the target itself moved, or whether the system is failing to hold a target that never moved.', 10, 1),
  ('mission-vec-control-03-o1-c1', 'solution', 'An unchanged setpoint rules out the target moving as the cause -- the loop is failing to hold a perfectly still target.', 20, 2),

  ('mission-vec-control-04-o1-c1', 'orientation', 'Error is a subtraction, not a measurement on its own.', 10, 1),
  ('mission-vec-control-04-o1-c1', 'solution', 'The error signal is setpoint minus measured value -- the one number every controller in this Act reacts to.', 20, 2),
  ('mission-vec-control-04-o2-c1', 'orientation', 'Look for a trace describing the error''s size across multiple swings, not a single reading.', 10, 1),
  ('mission-vec-control-04-o2-c1', 'solution', 'e1: the error signal crosses zero repeatedly and grows larger each swing rather than shrinking.', 20, 2),

  ('mission-vec-control-05-o1-c1', 'orientation', 'The correction is a multiplication of exactly one thing by a constant.', 10, 1),
  ('mission-vec-control-05-o1-c1', 'solution', 'Correction equals the current error times the gain constant Kp -- directly proportional, nothing else involved.', 20, 2),
  ('mission-vec-control-05-o2-c1', 'orientation', 'Think about what happens when the same physical system gets pushed harder for the exact same error.', 10, 1),
  ('mission-vec-control-05-o2-c1', 'solution', 'Correction grows with Kp, and past some point an overly aggressive correction can overshoot and provoke a larger error the other way.', 20, 2),

  ('mission-vec-control-06-o1-c1', 'orientation', 'This term does not react to the error right now -- it reacts to the error''s history.', 10, 1),
  ('mission-vec-control-06-o1-c1', 'solution', 'Integral control accumulates error over time, eliminating the small steady-state gap proportional control alone would leave.', 20, 2),
  ('mission-vec-control-06-o2-c1', 'orientation', 'Think about what happens to a proportional correction as the error itself shrinks toward zero.', 10, 1),
  ('mission-vec-control-06-o2-c1', 'solution', 'At a small enough error, the proportional correction itself becomes small enough to be balanced out, so the system simply stops closing the last bit of the gap.', 20, 2),

  ('mission-vec-control-07-o1-c1', 'orientation', 'This term does not care how big the error is -- it cares how quickly it is changing.', 10, 1),
  ('mission-vec-control-07-o1-c1', 'solution', 'Derivative control reacts to the rate of change of the error, easing off if the error is already closing quickly.', 20, 2),
  ('mission-vec-control-07-o2-c1', 'orientation', 'Think of derivative control as damping, not as another push in the same direction.', 10, 1),
  ('mission-vec-control-07-o2-c1', 'solution', 'An appropriately-sized derivative term adds damping, easing off as the error closes quickly, which tends to reduce overshoot rather than worsen it.', 20, 2),

  ('mission-vec-control-08-o1-c1', 'orientation', 'Ask what each term is actually looking at: the error''s size, its history, or its trend.', 10, 1),
  ('mission-vec-control-08-o1-c1', 'solution', 'Proportional reacts to the current error size, integral to how long a small error has persisted, derivative to how fast the error is changing.', 20, 2),
  ('mission-vec-control-08-o2-c1', 'orientation', 'A fast initial response followed by a permanent small offset is a very specific shape.', 10, 1),
  ('mission-vec-control-08-o2-c1', 'solution', 'A persistent, unchanging gap over time is exactly the symptom integral control exists to eliminate -- integral is the weak term here.', 20, 2),

  ('mission-vec-control-09-o1-c1', 'orientation', 'Tuning is about matching numbers to a machine, not writing code once.', 10, 1),
  ('mission-vec-control-09-o1-c1', 'solution', 'Tuning means choosing Kp, Ki and Kd to match a specific physical system''s real behavior -- a match that can stop being true if the physical system itself changes.', 20, 2),
  ('mission-vec-control-09-o2-c1', 'orientation', 'Look for a record about when the gain value was last touched, not about cosmetic maintenance.', 10, 1),
  ('mission-vec-control-09-o2-c1', 'solution', 'e1: Kp was set at commissioning decades ago with no record of ever being revisited -- that is the standing risk.', 20, 2),

  ('mission-vec-control-10-o1-c1', 'orientation', 'Ask whether each swing is getting bigger or smaller than the one before it.', 10, 1),
  ('mission-vec-control-10-o1-c1', 'solution', 'Damped oscillation shrinks toward the setpoint over time; growing oscillation gets larger each cycle and will not settle on its own.', 20, 2),
  ('mission-vec-control-10-o2-c1', 'orientation', 'Compare each swing''s peak deviation to the one right before it.', 10, 1),
  ('mission-vec-control-10-o2-c1', 'solution', 'r3: swing 3''s peak deviation is larger than swing 2''s, which was larger than swing 1''s -- growing oscillation, not damped.', 20, 2),

  ('mission-vec-control-11-o1-c1', 'orientation', 'Sampling rate is about timing, and timing affects both staleness and noise sensitivity.', 10, 1),
  ('mission-vec-control-11-o1-c1', 'solution', 'Sampling rate determines how often the loop measures, decides and acts -- too slow means stale data, too fast relative to noise means reacting to noise itself.', 20, 2),
  ('mission-vec-control-11-o2-c1', 'orientation', 'Look for a log describing the sampling rate''s history, not the arm''s appearance or power draw.', 10, 1),
  ('mission-vec-control-11-o2-c1', 'solution', 'e1: the sampling rate is unchanged for decades and within spec, which rules it out as a plausible cause of the new oscillation.', 20, 2),

  ('mission-vec-control-12-o1-c1', 'orientation', 'Look for evidence describing the sensor and controller communicating continuously, not a note about an unused backup mode.', 10, 1),
  ('mission-vec-control-12-o1-c1', 'concept', 'An open-loop failure would look like a fixed command with no ongoing correction at all -- this evidence describes the opposite.', 20, 2),
  ('mission-vec-control-12-o1-c1', 'solution', 'e1: continuous sensor reporting feeding continuous controller corrections, end to end with no break, confirms the loop is closed and active.', 30, 3),
  ('mission-vec-control-12-o2-c1', 'orientation', 'Nothing in this evidence describes anyone changing a number -- it describes the physical machine changing underneath the number.', 10, 1),
  ('mission-vec-control-12-o2-c1', 'concept', 'A gain chosen correctly for one mechanical response can become wrong for a different mechanical response, even if the gain value itself never moves.', 20, 2),
  ('mission-vec-control-12-o2-c1', 'solution', 'The proportional gain, correct for the arm''s original bearings, is now too aggressive for its current worn response -- the same correction now overcorrects.', 30, 3),
  ('mission-vec-control-12-o3-c1', 'orientation', 'Rule out the sampling record first, then look at which remaining record actually describes a trend across multiple cycles.', 10, 1),
  ('mission-vec-control-12-o3-c1', 'concept', 'A single reading cannot show growth -- only a sequence of readings compared to each other can.', 20, 2),
  ('mission-vec-control-12-o3-c1', 'solution', 'r2: each swing''s peak deviation exceeds the last, the signature of a correction that is consistently too strong for the arm''s current damping.', 30, 3),
  ('mission-vec-control-12-o4-c1', 'orientation', 'Combine all three findings into one story: what stayed the same, what changed, and what that means for a fix.', 15, 1),
  ('mission-vec-control-12-o4-c1', 'concept', 'The tuning was never wrong the day it was chosen. It became wrong gradually, as the physical machine aged past the assumptions baked into it.', 25, 2),
  ('mission-vec-control-12-o4-c1', 'solution', 'The loop is closed and healthy; the gain was correct for bearings that no longer exist in their original form; the fix is to retune -- lower the proportional gain and add damping suited to the arm as it is today, not as it was thirty years ago.', 35, 3);
